# Alpha diversity
####################
# Libraries#
library(tidyr)
library(dplyr)
library(tidyverse)
library(forcats)
###############################
# Read metadata
meta <- read.table(
  "usc-sediment-metadata.tsv",
  header = TRUE,
  row.names = 1,
  sep = "\t",
  check.names = FALSE,
  comment.char = "",
  quote = ""
)

#Loading the alpha diversity indices generated by QIIME2
#shannon
shannon <- read.table(
  "alpha-diversity-shannon.tsv",
  header = TRUE,
  row.names = 1,
  sep = "\t",
  check.names = FALSE
)

head(shannon) #checking the column name
colnames(shannon) <- "shannon" #changing it to shannon 

#observed features
observed <- read.table(
  "alpha-diversity-obsv-features.tsv",
  header = TRUE,
  row.names = 1,
  sep = "\t",
  check.names = FALSE
)

head(observed) #no need to change column name


#Pielou's Evenness
evenness <- read.table(
  "alpha-diversity-evenness.tsv",
  header = TRUE,
  row.names = 1,
  sep = "\t",
  check.names = FALSE
)

head(evenness)
colnames(evenness) <- "evenness" #changing it to evenness

#Faith's POD
faith <- read.table(
  "alpha-diversity-faith.tsv",
  header = TRUE,
  row.names = 1,
  sep = "\t",
  check.names = FALSE
)

head(faith) #not changing the column name

#make a dataframe of all the alpha indices merged with the metadata
#since we have consistent sample IDs, we can use inner join to retain samples that are common across all the indices 

alpha_list <- list(
  shannon = shannon,
  observed_features = observed,
  evenness = evenness,
  faith_pd = faith
)

alpha_list_clean <- imap(alpha_list, function(df, metric_name) {
  df %>%
    rownames_to_column("sample_id") %>%
    rename(value = 2) %>%
    rename(!!metric_name := value)
})

alpha_combined <- reduce(alpha_list_clean, inner_join, by = "sample_id")

alpha_metadata <- meta %>%
  rownames_to_column("sample_id") %>%
  inner_join(alpha_combined, by = "sample_id")

head(alpha_metadata)

#check if there were any metadata columns that got dropped
setdiff(rownames(meta), alpha_metadata$sample_id)


#convert to long form for plotting
alpha_long <- alpha_metadata %>%
  pivot_longer(
    cols = c(shannon, observed_features, evenness, faith_pd),
    names_to = "metric",
    values_to = "value"
  )

#Plotting the alphas
ggplot(alpha_long, aes(x = site, y = value, fill = site)) +
  geom_violin(trim = FALSE, alpha = 0.5) +
  geom_boxplot(width = 0.15, outlier.shape = NA, alpha = 0.8) +
  geom_jitter(width = 0.12, size = 2, alpha = 0.9) +
  facet_wrap(~ metric, scales = "free_y") +
  theme_classic() +
  theme(
    axis.text.x = element_text(angle = 45, hjust = 1),
    legend.position = "none"
  ) +
  labs(
    x = "Site",
    y = "Alpha diversity value",
    title = "Alpha diversity across sites"
  )

#Kruskal-wallis tests
alpha_kruskal_site <- alpha_long %>%
  group_by(metric) %>%
  summarise(
    statistic = kruskal.test(value ~ site)$statistic,
    df = kruskal.test(value ~ site)$parameter,
    p_value = kruskal.test(value ~ site)$p.value,
    .groups = "drop"
  ) %>%
  mutate(p_adj = p.adjust(p_value, method = "BH"))

alpha_kruskal_site

#alpha diversity metrics across sites were not signifnicant 

ggplot(alpha_long, aes(x = site, y = value, fill = site)) +
  geom_violin(trim = FALSE, alpha = 0.5) +
  geom_boxplot(width = 0.15, outlier.shape = NA, alpha = 0.8) +
  geom_jitter(width = 0.12, size = 2, alpha = 0.9) +
  stat_summary(
    fun = mean,
    geom = "point",
    shape = 23,
    size = 3,
    fill = "white"
  ) +
  stat_summary(
    fun = mean,
    geom = "text",
    aes(label = round(after_stat(y), 2)),
    vjust = -1,
    size = 3
  ) +
  facet_wrap(~ metric, scales = "free_y") +
  theme_classic() +
  theme(
    axis.text.x = element_text(angle = 45, hjust = 1),
    legend.position = "none",
    strip.text = element_text(face = "bold")
  ) +
  labs(
    x = "Site",
    y = "Alpha diversity value",
    title = "Alpha diversity across sites"
  )



