#had to correct spelling of a site
alpha_long <- alpha_long %>%
  mutate(
    site = recode(site,
                  "Madredijos" = "Madridejos")
  )

site_order <- c("Madridejos", "Panitugan", "Sta-Fe", "OIWS-1", "OIWS-2")

alpha_long2 <- alpha_long %>%
  mutate(
    forest_type = case_when(
      site %in% c("Madridejos", "Panitugan", "Sta-Fe") ~ "Natural",
      site %in% c("OIWS-1", "OIWS-2") ~ "Planted",
      TRUE ~ NA_character_
    ),
    forest_type = factor(forest_type, levels = c("Natural", "Planted")),
    site = factor(site, levels = site_order)
  )

ggplot(alpha_long2, aes(x = site, y = value, fill = site)) +
  geom_violin(trim = FALSE, alpha = 0.5) +
  geom_boxplot(width = 0.15, outlier.shape = NA, alpha = 0.8) +
  geom_jitter(width = 0.12, size = 2, alpha = 0.9) +
  stat_summary(
    fun = mean,
    geom = "point",
    shape = 23,
    size = 3,
    fill = "white"
  ) +
  stat_summary(
    fun = mean,
    geom = "text",
    aes(label = round(after_stat(y), 2)),
    vjust = -1,
    size = 3
  ) +
  facet_grid(
    metric ~ forest_type,
    scales = "free",
    space = "free_x"
  ) +
  theme_classic() +
  theme(
    axis.text.x = element_text(angle = 45, hjust = 1),
    legend.position = "none",
    strip.text = element_text(face = "bold"),
    strip.background = element_rect(fill = "white", color = "black")
  ) +
  labs(
    x = "Site",
    y = "Alpha diversity value",
    title = "Alpha diversity across sites by forest type"
  )


